// src/harness/adapter.ts (sketch). Adapter instances, the send queue, pendingSwitch settlement and the turn state machine live only in main (electron/harness/*, electron/session/*);
// src/harness/adapters/* is only an IPC proxy and pure-function bindings. Components read only useCaps(chatId); harness names appear only in adapters/* and electron/harness/*.
export type HarnessKind = 'codex' | 'claude' | `acp:${string}`;   // two first-class harnesses; basic tier: acp:dsh, acp:opencode, acp:kimi, acp:qwen…
export type NativeRef = { kind: HarnessKind; id: string; instance: string };            // resolved per segment; settle pendingSwitch first
export type Semantic = 'goal' | 'plan' | 'review' | 'multiAgent' | 'deepReasoning' | 'compact' | 'init' | 'skills'
  | 'memory' | 'tasks' | 'workflows' | 'shell' | 'rename' | 'fork' | 'rewind' | 'temporary' | 'archive' | 'search'
  | 'clear' | 'model' | 'effort' | 'speed' | 'permissions' | 'mcp' | 'status' | 'feedback' | 'logout' | 'voiceChat'
  | 'cloud' | 'textGen' | 'computerUse' | 'browser' | 'dictation';                       // 33 of them; every row of commandLayer.table has a matching entry
export type Why = { layer: 'harness' | 'version' | 'provider' | 'model' | 'account' | 'flag' | 'session'; code: string;
  fix?: 'signIn' | 'install' | 'upgrade' | 'enableFeature' | 'switchModel' | 'switchHarness' | 'newChat' | 'wait' };
// version layer = runtime probe failed (e.g. getSettings does not exist); presented the same as disabled, and turns off only this one capability
export type Binding =
  | { via: 'rpc'; method: string }                     // codex review/start, thread/goal/set
  | { via: 'passthrough'; template: string }           // claude '/goal {args}' (may only go in the last block); kimi '/goal {args}'
  | { via: 'config'; option: string; value: unknown }  // codex effort=ultra; claude ultracode=true
  | { via: 'polyfill'; engine: 'init' | 'shell' | 'archive' | 'search' }   // serves first-class harnesses only; basic tier has no polyfill
  | { via: 'route'; to: 'codex' | 'claude' }           // voiceChat → codex; for basic tier, ⇧⌘N → claude or codex
  | { via: 'none'; why: Why };
/** Presentation depends only on Why.layer: harness layer → context entry points absent, global entry points route or absent; other layers → all entry points disabled with a fix */
export type CapState = 'native' | 'sage' | 'route' | 'disabled' | 'absent';

export interface StaticInfo {                          // layer 1: static, roughly an ACP registry entry
  kind: HarnessKind; label: string; vendor: string; tier: 'first' | 'basic';
  channel: 'app-server' | 'agent-sdk' | 'acp';
  detect: { bins: string[]; installCmd?: string; installUrl: string };   // detected using the login shell's PATH; Settings lets the user pick a bin manually
  versions: { min: string; knownBad: string[]; tested: string[] };      // above min and not in knownBad works as usual; only capabilities whose probe fails are greyed out
  wires: ('anthropic' | 'responses' | 'chat')[]; instructionsFiles: string[]; skillRoots: string[];
  docsUrl: string; dataNotes: string[]; resumeCommand(nativeId: string): string | null;
  quirks?: string;                                     // basic tier: electron/harness/acp/quirks/<id>.cjs
  privacyDefaults?: string[];                          // required for basic tier: default uploads and telemetry to turn off in the launch arguments; if missing, it does not enter the picker
  admission?: { requireToolHandshake: true; handshakeTimeoutMs: number; privacyGate?: string };   // dsh: '--dump-config'
}
export interface Negotiated {                          // layer 2: negotiated per (harness, instance); anything undeclared is treated as unsupported
  cliVersion: string;                                  // Claude takes init.claude_code_version; Codex parses initialize.userAgent
  versionStatus: 'ok' | 'unverified' | 'knownBad';
  probes: Record<string, boolean>;                     // e.g. claude.getSettings, claude.perTaskStop, codex.pluginDisable, codex.threadProviders
  prompt: { image: string[]; pdf: boolean; humanOrigin: boolean; slashLastBlockOnly: boolean };
  session: { load: boolean; resume: boolean; fork: 'none' | 'whole' | 'upToTurn'; rewind: boolean;
    ephemeral: 'native' | 'none'; perTaskStop: boolean; history: 'native' | 'sage' };
  permissions: { scope: 'turn' | 'session'; remember: 'native' | 'none' };
  approvals: ApprovalKind[];
  toolInjection: 'sdkMcp' | 'threadConfigMcp' | 'sessionMcp';   // each harness has exactly one channel; a basic-tier harness without sessionMcp is not admitted
  events: { turnEnd: boolean; usage: 'cost' | 'tokens' | 'context' | 'none'; tasks: 'stoppable' | 'cancelAll' | 'none' };
  accounts: { failover: 'inRequest' | 'restartResume' | 'none'; perChat: boolean; usage: 'live' | 'polled' | 'none' };
  ext: Partial<Record<'realtimeVoice' | 'cloudTasks' | 'feedbackUpload' | 'remoteControl' | 'outputStyle', true>>;
}
export interface SessionState {                        // layer 3: dynamic session state, held by main; a window takes a snapshot first, then applies patches by rev, and refetches on a gap
  rev: number;
  turn: 'idle' | 'running' | 'awaitingUser' | 'crashed'; runningElsewhere: boolean;   // Composer is greyed out while an external client is running a turn
  config: ConfigOption[]; modes: ModeOption[]; mode: string; plan: boolean; commands: CommandInfo[];
  goal: GoalSnapshot | null; tasks: TaskSnapshot[]; context: { used: number; window: number } | null;
}
export interface ConfigOption { id: string; name: string; type: 'select' | 'boolean'; currentValue: unknown;
  category: 'mode' | 'model' | 'model_config' | 'thought_level' | `_sage.${string}`;   // same shape as ACP configOptions
  options?: { value: unknown; name: string; why?: Why }[] }
export interface ModeOption { id: string; label: string; anchor: 'readOnly' | 'ask' | 'auto' | 'full'; note?: string }   // for basic tier, a mode with no anchor is treated as ask
export interface CommandInfo { name: string; aliases?: string[]; description: string; hint?: string; semantic?: Semantic; why?: Why;
  source: 'app' | 'builtin' | 'skill' | 'workflow' | 'plugin' | 'custom'; dispatch: 'ui' | 'passthrough' | 'rpc' | 'polyfill' }
export interface GoalSnapshot { objective: string;
  status: 'active' | 'paused' | 'blocked' | 'budgetLimited' | 'usageLimited' | 'complete' | 'failed';
  controls: ('pause' | 'resume' | 'budget' | 'edit' | 'clear')[];      // codex has the full set; claude has pause, resume, budget, clear
  pauseBy: 'harness' | 'sage';                         // claude's pause is held by Sage: interrupt() then '/goal clear', with the condition stored in meta.goalHeld
  budgetBy: 'harness' | 'sage' | null;                 // codex tokenBudget (soft cap, settled per turn); for claude, Sage counts Stop hook rounds
  source: 'rpc' | 'syntheticMessages';                 // claude: the 'Goal set:' synthetic message, 'Stop hook feedback' count, transcript goal_status
  rounds?: number; tokens?: number; budget?: { rounds?: number; tokens?: number; soft: boolean }; lastReason?: string }
export interface TaskSnapshot { id: string; kind: 'workflow' | 'agent' | 'shell' | 'monitor' | 'cron' | 'review';
  name: string; status: string; stoppable: boolean }
export type ApprovalKind = 'command' | 'fileChange' | 'permissions' | 'question' | 'elicitation' | 'tool' | 'plan'
  | 'computerAccess' | 'browserOrigin' | 'computerConfirm';
export type SageInputPart = { type: 'text' | 'image' | 'file' | 'skill' | 'mention' | 'selection' | 'handoff'; value: string };
export interface ProviderProfile { id: string; wires: ('anthropic' | 'responses' | 'chat')[]; baseUrl: string; firstParty: boolean;
  models: ModelInfo[]; drops: string[];                // mopilot's drops come from WP0's gateway capability table
  effortLevels?: string[]; compactWindow?: number; visionFallbackModel?: string | null }
export interface ModelInfo { id: string; label: string; input: ('text' | 'image')[] | 'unknown';   // basic tier is handled as 'unknown'
  efforts: string[]; ultra: boolean; serviceTiers: string[] }       // the codex luna series has no ultra; serviceTiers has only priority
export interface AccountCaps { billing: 'subscription' | 'apiKey' | 'credits'; perChat: boolean; fast: boolean }
export type FeatureFlags = Record<string, boolean>;    // remote switches plus the harness's own features.* (codex reads experimentalFeature/list)
export interface SageToolset { serverName: string; token: string; tools: string[] }   // serverName = sage_<per-session random nonce>
export type SageItem = { id: string; kind: string; [k: string]: unknown };            // v2 item plus Sage extension items: goal, task, commandOutput, switchNote, computerAction

export interface HarnessAdapter {                      // instantiated only in main
  info: StaticInfo;
  negotiate(instance: string): Promise<Negotiated>;
  bindings(n: Negotiated, s: SessionState | null): Record<Semantic, Binding>;   // Record: every semantic must take a position
  start(o: { cwd: string; instance: string; config: Record<string, unknown>; ephemeral: boolean; tools: SageToolset }): Promise<NativeRef>;
  send(r: NativeRef, m: { parts: SageInputPart[]; origin: 'human' | 'sage'; uuid: string }): Promise<void>;   // the adapter is responsible for serialization and block order
  invoke(r: NativeRef, s: Semantic, args: string): Promise<void>;
  interrupt(r: NativeRef, o: { pauseGoal: boolean; keepBackground: boolean }): Promise<void>;
  stopTask?(r: NativeRef, taskId: string): Promise<void>;                        // must be implemented when tasks:'stoppable' is declared
  setConfig(r: NativeRef, id: string, value: unknown): Promise<SessionState>;
  setMode(r: NativeRef, mode: string, plan: boolean): Promise<SessionState>;
  answer(r: NativeRef, requestId: string, optionId: string, note?: string): Promise<void>;
  history(r: NativeRef, cursor?: string): Promise<{ items: SageItem[]; next?: string }>;   // reads Sage's own store when history:'sage'
  reconcile(r: NativeRef): Promise<SessionState>;     // re-read native state when the rollout or jsonl is rewritten by an external client
  events(r: NativeRef, on: (e: SageItem | Partial<SessionState> | { crashed: string }) => void): () => void;
}
/** Effective capability = harness ∩ provider ∩ model ∩ account ∩ flag ∩ session; the first layer that gives none supplies the Why; a polyfill replaces it only when a first-class harness is none at the harness layer and the criteria are met */
export declare function resolveCaps(a: HarnessAdapter, n: Negotiated, p: ProviderProfile, m: ModelInfo,
  acct: AccountCaps, flags: FeatureFlags, s: SessionState | null): Record<Semantic, Binding>;
